import React, { useEffect, useState } from 'react';
import tableIcons from "../Inbox/MaterialTableIcons";
import { confirmAlert } from "react-confirm-alert";
import { URL } from "../URLConstant";
import MaterialTable, { MTableToolbar } from "material-table";
import { log2 } from 'pdfjs-dist';
import Modal from "react-responsive-modal";
import "./addOrViewTempGrpUers.css";

var Loader = require("react-loader");

function ReqUsrForCorp(props) {

    const [reqCorpDetails, setReqCorpDetails] = useState([]);

    const [allowModal, setAllowModal] = useState(false);

    const [eachRequstesList, setEachRequstesList] = useState([]);

    const [eachReqListFrMakMem, setEachReqListFrMakMem] = useState([]);

    const [allowTocheck, setAllowTocheck] = useState(true);

    const [allgrpNameAndCodeList, SetAllgrpNameAndCodeList] = useState({});

    const [designation, setdesignation] = useState("");

    const [desgntinApproved, setdesgntinApproved] = useState(false);

    const [userEmpyDetail, setUserEmpyDetail] = useState({
        UserName: "",
        RequestedOn: "",
        UserCorpId: "",
        loginName: "",
        corpMember: ""
    });

    // fetch API to get the list of requested members who has raised to 
    //become the member of corp entity and for group access
    useEffect(() => {
        const options = {
            method: "POST",
            headers: {
                "Content-type": "application/json"
            },
            body: JSON.stringify({
                authToken: sessionStorage.getItem("authToken")
            })
        }

        fetch(URL.getCorpMemberRequests, options)
            .then(response => (response.json()))
            .then(data => {
                if (data.status === "SUCCESS") {
                    setReqCorpDetails(data.userDetails);
                    SetAllgrpNameAndCodeList(data.grpNameAndCodList);
                }
                else if (data.statusDetails === "Session Expired") {
                    confirmAlert({
                        message: data.statusDetails,
                        buttons: [
                            {
                                label: "OK",
                                className: "confirmBtn",
                                onClick: () => {
                                    props.history.push("/login");
                                },
                            },
                        ], closeOnClickOutside: false // Set to false to prevent closing on click outside
                    });
                }
                else {
                    confirmAlertFunction(data.statusDetails);
                }
            })
            .catch(error => {
                console.log(error);
                confirmAlertFunction(`Something went wrong. please try again!`);
            })
    }, [])

    // column name in materail table..
    const columns = [
        {
            title: "",
            field: "",
            cellStyle: {
                width: "2%",

            }
        },
        {
            title: "Name",
            field: "firstName",
            cellStyle: {
                width: "23%",
                paddingLeft: "2px"
            }
        },
        {
            title: "Requested On",
            field: "requested_On",
            cellStyle: {
                width: "25%",
                paddingLeft: "3px"
            }
        },
        {
            title: "Corp Employee ID",
            field: "userCorpID",
            cellStyle: {
                width: "25%",
            }
        },
        {
            title: "Request details",
            cellStyle: {
                paddingLeft: "0px",
                width: "25%",
            },
            render: (rowData) => {
                return (
                    <div style={{ paddingLeft: "20%" }}>
                        <button
                            className='btn btn-success'
                            type="submit"
                            style={{ color: "white", fontSize: "12px", backgroundColor: "#20a8d8", borderColor: "#20a8d8" }}
                            onClick={(event) =>
                                viewGrpRequested(event, rowData)
                            }
                        >
                            View
                        </button>
                    </div>
                );
            },
        },
    ];

    // one consent confirmAlert that is used allover.
    const confirmAlertFunction = (message) => {
        confirmAlert({
            message: message,
            buttons: [
                {
                    label: "OK",
                    className: "confirmBtn"
                }
            ],
            closeOnClickOutside: false, // Set to false to prevent closing on click outside
        });
    }

    // Logic to open checkBox on reject of all group to be a member of corp entity..
    const accpRecjValue = (event, inputId, key) => {
        let allFalse = true;
        if (!(userEmpyDetail.corpMember === "1")) {
            if (inputId.includes("Reject")) {
                eachReqListFrMakMem[key] = true;
            }
            else {
                eachReqListFrMakMem[key] = false;
            }
            for (let key in eachReqListFrMakMem) {
                // if one of the value is false it indicates one of the groups are rejected
                if (!eachReqListFrMakMem[key]) {
                    allFalse = false;
                } else {
                    continue;
                }
            }
            // checking designation if it is accepted or rejected.
            // if the desgntinApproved is false it indicates it is rejected.
            // allow checkBox..
            if (allFalse && !JSON.parse(desgntinApproved)) {
                setAllowTocheck(false);
            }
            else {
                setAllowTocheck(true);
            }
        }
    }

    //collecting the designation approval/rejection value..
    const handleRadioChange = (e) => {
        setdesgntinApproved(e.target.value);
        // checking weather the request groups are empty.. 
        // if it is empty and only designation is seleted and if the designation is rejected
        // allow the checkBox to to either make them as member of corpoarte.
        if (eachRequstesList.length === 0 && (e.target.value === "false")) {
            setAllowTocheck(false);
        }
        // else case the accept is selected hide the checkBox.
        if (e.target.value === "true") {
            setAllowTocheck(true);
        }
        // when groups are also present checking if they are rejected
        // if rejected allow checkBox..
        let allFalse = true;
        for (let key in eachReqListFrMakMem) {
            if (!eachReqListFrMakMem[key]) {
                allFalse = false;
            } else {
                continue;
            }
        }
        // if all groups are rejected and designation is rejected allow checkBox..
        if (allFalse && (e.target.value === "false")) {
            setAllowTocheck(false);
        }
        // else dont allow checkBox..
        else {
            setAllowTocheck(true);
        }
    };

    // on click of view button below () is used to set the data's to the state..
    const viewGrpRequested = (event, data) => {
        event.preventDefault();
        //checking whether the designation key is present for approval/rejection request
        if (data?.hasOwnProperty("designation")) {
            setdesignation(data.designation);
        }

        // if the requested request doesnt contain any groups or designation. Provide option to check.
        if (!(data?.hasOwnProperty("designation")) && data.reqstdGroups.length === 0) {
            setAllowTocheck(false);
        }

        setAllowModal(true);
        setEachRequstesList(data.reqstdGroups);
        for (let key in data.reqstdGroups) {
            setEachReqListFrMakMem(oldvalue => ({
                ...oldvalue,
                [data.reqstdGroups[key]]: false
            }))
        }
        setUserEmpyDetail({
            UserName: data.firstName,
            RequestedOn: data.requested_On,
            UserCorpId: data.userCorpID,
            loginName: data.loginName,
            corpMember: data.corpMember
        })

    }

    // to close the modal..
    const closeTheModal = (event, boolean) => {
        setAllowModal(false);
    }

    //to view the list of requested grps and other details.
    const openModalForReqGrp = () => {
        return (
            <>
                <div
                    style={{ display: "flex", marginBottom: "5px" }}
                    className="rejectedByCss"
                >
                    <div style={{ fontStyle: "inherit", fontSize: "13px", width: "50%", display: "flex" }}>
                        <div style={{ width: "85%" }}>Name </div> <div>:</div>
                    </div>
                    <div style={{ fontSize: "13px", width: "50%" }}>
                        <span>{userEmpyDetail.UserName}</span>
                    </div>
                </div>
                <div
                    style={{ display: "flex", marginBottom: "5px" }}
                    className="rejectedByCss"
                >
                    <div
                        style={{ fontStyle: "inherit", fontSize: "13px", width: "50%", display: "flex" }}
                    >
                        <div style={{ width: "85%" }}>Requested On </div><div>:</div>
                    </div>
                    <div style={{ fontSize: "13px", width: "50%" }}>
                        <span>{userEmpyDetail.RequestedOn}</span>
                    </div>
                </div>
                <div
                    style={{ display: "flex", marginBottom: "5px" }}
                    className="rejectedByCss"
                >
                    <div
                        style={{ fontStyle: "inherit", fontSize: "13px", width: "50%", display: "flex" }}
                    >
                        <div style={{ width: "85%" }}>Corp Employee ID </div><div>:</div>
                    </div>
                    <div style={{ fontSize: "13px", width: "50%" }}>
                        <span>{userEmpyDetail.UserCorpId}</span>
                    </div>


                </div>

                <div hidden={designation !== "" ? false : true} id="adddesignation" className='inputname1' style={{ paddingTop: "5px", width: "100%" }}>
                    {
                        <>
                            <div style={{ width: "85%" }}>Designation </div>
                            <div className="GrpList  ScrollBarForApprove" style={{ width: "100%", height: "fit-content", border: "3px solid #9dc1e3", fontSize: "13px", borderRadius: "5px", padding: "5px" }}>
                                <>
                                    <div style={{ display: "flex", width: "100%", paddingBottom: "5px" }}>
                                        <div style={{ width: "60%", paddingTop: "2px" }}><span>{designation}</span></div>
                                        <div style={{ width: "20%", paddingRight: "10px", display: "flex" }}>
                                            <div style={{ paddingTop: "3px" }}>
                                                <input type="radio" id='acptDesignation' name="acceptAndReject" value={true} onChange={handleRadioChange} />
                                            </div>
                                            <div style={{ paddingRight: "3px", color: "green" }}>Accept</div></div>
                                        <div style={{ width: "20%", display: "flex" }}>
                                            <div style={{ paddingTop: "3px" }} >
                                                <input type="radio" id='rejtDesignation' name="acceptAndReject" value={false} onChange={handleRadioChange} />
                                            </div>
                                            <div style={{ paddingRight: "3px", color: "red" }}>Reject</div></div>
                                    </div>
                                </>


                            </div>
                        </>
                    }
                </div>

                <div hidden={eachRequstesList.length != 0 ? false : true} className='inputname1' style={{ paddingTop: "5px", width: "100%" }}>
                    {
                        <>
                            <div style={{ width: "85%" }}>Requested Groups </div>
                            <div className="GrpList  ScrollBarForApprove" style={{ width: "100%", height: "fit-content", border: "3px solid #9dc1e3", fontSize: "13px", borderRadius: "5px", padding: "5px" }}>
                                {
                                    eachRequstesList.map((posts, index) => (
                                        <>
                                            <div style={{ display: "flex", width: "100%", paddingBottom: "5px" }} key={index}>
                                                <div style={{ width: "60%", paddingTop: "2px" }}><span>{allgrpNameAndCodeList[posts]}</span></div>
                                                <div style={{ width: "20%", paddingRight: "10px", display: "flex" }}> <div style={{ paddingTop: "3px" }}><input onChange={e => accpRecjValue(e, `${posts}Accept`, posts)} type='radio' name={`acceptAndReject${posts}`} id={`${posts}Accept`} /></div><div style={{ paddingRight: "3px", color: "green" }}>Accept</div></div>
                                                <div style={{ width: "20%", display: "flex" }}><div style={{ paddingTop: "3px" }} ><input onChange={e => accpRecjValue(e, `${posts}Reject`, posts)} type='radio' name={`acceptAndReject${posts}`} id={`${posts}Reject`} /></div> <div style={{ paddingRight: "3px", color: "red" }}>Reject</div></div>
                                            </div>
                                        </>
                                    ))
                                }
                            </div>
                        </>
                    }
                </div>
                <div id='corpMemCss' hidden={allowTocheck}>
                    <div style={{ marginRight: '3px', paddingTop: "2px" }}><input type='checkBox' name='shall_Be_Corp_Member' id='shallBeCorpMember' /></div>
                    <div>should be a corporate member?</div>
                </div>
            </>
        )

    }

    // final submittion call for approve or rejection of groups..
    const accptReqGrp = (event) => {
        event.preventDefault();
        event.preventDefault();
        let acceptedGrp = [];
        let rejectedGrp = [];

        // checking the designation..
        if (designation !== "" && !document.getElementById('rejtDesignation').checked && !document.getElementById('acptDesignation').checked) {
            confirmAlertFunction('Either reject or accept the designation!');
            return;
        }

        // validating the groups. either accept or reject should be selected..
        for (let key in eachRequstesList) {
            // if sys Users has not selected any of the options, below alert is showen..
            if (!document.getElementById(`${eachRequstesList[key]}Accept`).checked && !document.getElementById(`${eachRequstesList[key]}Reject`).checked) {
                confirmAlertFunction(`Select the option for '${allgrpNameAndCodeList[eachRequstesList[key]]}' before submit!`);
                return;
            }
            else if (document.getElementById(`${eachRequstesList[key]}Accept`).checked) {
                acceptedGrp.push(eachRequstesList[key]);
            }
            else {
                rejectedGrp.push(eachRequstesList[key]);
            }
        }



        closeTheModal();
        setAllowModal(false);
        let isCorpMember = "";
        // below if condition is used to check if the system user has selected him to be a part of corpmember..
        if (!allowTocheck) {
            if (document.getElementById("shallBeCorpMember").checked) {
                isCorpMember = "1";
            }
            else {
                isCorpMember = "0";
            }
        }
        // based on server response checking if he is already an member of corp or not..
        else if (userEmpyDetail.corpMember === "1") {
            isCorpMember = "0";
        }
        else {
            isCorpMember = "1";
        }
        let userDetails = [{
            loginName: userEmpyDetail.loginName,
            addedGroups: acceptedGrp,
            rejectedGroups: rejectedGrp,
            UserCorpId: userEmpyDetail.UserCorpId,
            isCorpMember: isCorpMember
        }];

        // API call to add the users to there respective grps..
        const options = {
            method: "POST",
            headers: {
                "Content-type": "application/json"
            },
            body: JSON.stringify({
                designation: designation,
                isdesgntnApprd: JSON.parse(desgntinApproved),
                authToken: sessionStorage.getItem("authToken"),
                userDetails: userDetails,
                userIP: sessionStorage.getItem("userIP"),
            })
        };
        fetch(URL.approveCorpMemberRequests, options)
            .then(response => (response.json()))
            .then(data => {
                if (data.status === "SUCCESS") {
                    setAllowModal(false);
                    confirmAlert({
                        message: data.statusDetails,
                        buttons: [
                            {
                                label: "OK",
                                className: "confirmBtn",
                                onClick: () => {
                                    window.location.reload();
                                },
                            },
                        ],
                    });
                }
                else if (data.statusDetails === "Session Expired") {
                    setAllowModal(false);
                    confirmAlert({
                        message: data.statusDetails,
                        buttons: [
                            {
                                label: "OK",
                                className: "confirmBtn",
                                onClick: () => {
                                    props.history.push("/login");
                                },
                            },
                        ],
                    });
                }
                else {
                    setAllowModal(false);
                    confirmAlertFunction(data.statusDetails);
                }
            })
            .catch(error => {
                console.log(error);
                confirmAlertFunction(`Something went wrong. please try again!`);
            });
    }

    return (
        <>
            <Loader
                loaded={true}
                lines={13}
                radius={20}
                corners={1}
                rotate={0}
                direction={1}
                color="#000"
                speed={1}
                trail={60}
                shadow={false}
                hwaccel={false}
                className="spinner loader"
                zIndex={2e9}
                top="50%"
                left="50%"
                scale={1.0}
                loadedClassName="loadedContent"
            />
            <MaterialTable
                columns={columns}
                icons={tableIcons}
                data={reqCorpDetails}
                options={{
                    search: true,
                    thirdSortClick: false,
                    detailPanelType: "single",
                    detailPanelColumnAlignment: "right",
                    actionsColumnIndex: -1,
                    padding: "dense",
                    sorting: true,
                    showTitle: false,
                    headerStyle: {
                        borderTop: "2px inset ",
                        top: 0,
                        borderTopWidth: "2px",
                        backgroundColor: "#e8eaf5",
                        color: "black",
                        fontWeight: "normal",
                        fontSize: "16px",
                        paddingLeft: "2px",
                        borderBottom: "2px inset ",
                    },
                    searchFieldStyle: {
                        marginTop: "0px",
                        paddingTop: "0px",
                        paddingRight: "0px",
                        color: "Black",
                        top: "0px",
                        marginBottom: "20px",
                        border: "outset",
                    },
                    pageSize: 10,
                    pageSizeOptions: [10, 15, 20],
                }}
                components={{
                    // ---------Overriding the Toolbar Component and customised-----------
                    Toolbar: (props) => (
                        <div
                            style={{
                                backgroundColor: "#e8eaf5",
                                height: "35px",
                                fontSize: "6px",
                            }}
                        >
                            <MTableToolbar {...props} />
                        </div>
                    ),
                }}
            ></MaterialTable>
            {
                allowModal && (
                    <div className="custom-modal">
                        <div className="CustomModal-content">
                            <span className="close" onClick={closeTheModal}>&times;</span>
                            <div className='headingOfModalXcss'>
                                <span style={{ fontSize: "20px" }}>Request Details</span>
                            </div>
                            {
                                openModalForReqGrp()
                            }
                            <div className='Divo6Css'>
                                <div className='proceedCancelCss'>
                                    <button className='cancelbtn' type='button' onClick={closeTheModal}>Cancel</button>
                                </div>
                                <div className='proceedCancelCss'>
                                    <button className='proceedbtnX' type='button' onClick={e => accptReqGrp(e)}>Submit</button>
                                </div>
                            </div>
                        </div>
                    </div>
                )
            }
        </>
    )

}

export default ReqUsrForCorp